  1	import React, { useState, useEffect } from 'react';
  2	import { useStore } from '@/core/store';
  3	import { useShallow } from 'zustand/react/shallow';
  4	import {
  5	    Globe,
  6	    LayoutGrid,
  7	    Layers,
  8	    Radio,
  9	    Maximize2,
 10	    Columns,
 11	    X,
 12	    Sparkles,
 13	    Users,
 14	} from 'lucide-react';
 15	import { cn } from '@/lib/utils';
 16	import { BoardroomBrowserView } from './BoardroomBrowserView';
 17	import { BoardroomModulePreview } from './BoardroomModulePreview';
 18	import { BoardroomWorkbenchView } from './BoardroomWorkbenchView';
 19	import { BoardroomAgentFeedView } from './BoardroomAgentFeedView';
 20	import { AVAILABLE_AGENTS } from './ParticipantSelector';
 21	import type { BoardroomWorkspaceTab } from '@/core/store/slices/boardroomSlice';
 22	import {
 23	    judgeBoardroomWorkspaceRecommendation,
 24	    type BoardroomWorkspaceRecommendation,
 25	} from '@/config/typesafeJudgments';
 26	
 27	interface BoardroomWorkspacePaneProps {
 28	    hasOverlayOpen?: boolean;
 29	}
 30	
 31	export function BoardroomWorkspacePane({ hasOverlayOpen = false }: BoardroomWorkspacePaneProps) {
 32	    const {
 33	        boardroomWorkspaceLayout,
 34	        setBoardroomWorkspaceLayout,
 35	        boardroomWorkspaceTab,
 36	        setBoardroomWorkspaceTab,
 37	        setBoardroomPreviewModuleId,
 38	        agentHistory,
 39	        activeAgents,
 40	        toggleAgent,
 41	        soloAgent,
 42	        isCommandMenuOpen,
 43	    } = useStore(
 44	        useShallow(state => ({
 45	            boardroomWorkspaceLayout: state.boardroomWorkspaceLayout,
 46	            setBoardroomWorkspaceLayout: state.setBoardroomWorkspaceLayout,
 47	            boardroomWorkspaceTab: state.boardroomWorkspaceTab,
 48	            setBoardroomWorkspaceTab: state.setBoardroomWorkspaceTab,
 49	            setBoardroomPreviewModuleId: state.setBoardroomPreviewModuleId,
 50	            agentHistory: state.agentHistory || [],
 51	            activeAgents: state.activeAgents || [],
 52	            toggleAgent: state.toggleAgent,
 53	            soloAgent: state.soloAgent,
 54	            isCommandMenuOpen: state.isCommandMenuOpen ?? false,
 55	        }))
 56	    );
 57	
 58	    const [rawJevRecommendation, setJevRecommendation] = useState<BoardroomWorkspaceRecommendation | null>(null);
 59	    const jevRecommendation = agentHistory.length > 0 ? rawJevRecommendation : null;
 60	
 61	    useEffect(() => {
 62	        let isMounted = true;
 63	        if (agentHistory.length > 0) {
 64	            void judgeBoardroomWorkspaceRecommendation(agentHistory)
 65	                .then(rec => {
 66	                    if (isMounted) setJevRecommendation(rec);
 67	                })
 68	                .catch(() => {});
 69	        }
 70	        return () => {
 71	            isMounted = false;
 72	        };
 73	    }, [agentHistory]);
 74	
 75	    const tabs: { id: BoardroomWorkspaceTab; label: string; icon: React.ElementType }[] = [
 76	        { id: 'browser', label: 'Live Browser', icon: Globe },
 77	        { id: 'module', label: 'Studio Preview', icon: LayoutGrid },
 78	        { id: 'workbench', label: 'Asset Workbench', icon: Layers },
 79	        { id: 'agent-feed', label: 'Agent Live Feed', icon: Radio },
 80	    ];
 81	
 82	    const isStage = boardroomWorkspaceLayout === 'stage';
 83	    const recommendedTabMeta = jevRecommendation
 84	        ? tabs.find(t => t.id === jevRecommendation.recommendedTab)
 85	        : undefined;
 86	    const recommendedTabLabel = recommendedTabMeta?.label ?? jevRecommendation?.recommendedTab;
 87	
 88	    return (
