 11313	export function heuristicBoardroomWorkspaceRecommendation(
 11314	    messages: { role: string; text?: string }[]
 11315	): BoardroomWorkspaceRecommendation {
 11316	    const combined = messages
 11317	        .slice(-5)
 11318	        .map(m => m.text || '')
 11319	        .join(' ')
 11320	        .toLowerCase();
 11321	
 11322	    if (/(split(\s|_|-)?sheet|contract|clearance|copyright|agreement|assignment|terms)/.test(combined)) {
 11323	        return {
 11324	            recommendedTab: 'workbench',
