 11327	            reasoningHint: 'Active discussion on contracts & split sheets detected.',
 11328	            source: 'deterministic',
 11329	        };
 11330	    }
 11331	
 11332	    if (/(cover(\s|_|-)?art|visual|artwork|video|teaser|font|render|3d|canvas|animation)/.test(combined)) {
 11333	        return {
 11334	            recommendedTab: 'module',
 11335	            recommendedModule: 'creative',
 11336	            confidence: 0.88,
 11337	            reasoningHint: 'Visual & creative production discussion detected.',
 11338	            source: 'deterministic',
 11339	        };
 11340	    }
 11341	
 11342	    if (/(budget|invoice|royalt|expense|payout|accounting|tax|revenue|financial)/.test(combined)) {
 11343	        return {
 11344	            recommendedTab: 'module',
 11345	            recommendedModule: 'finance',
 11346	            confidence: 0.88,
 11347	            reasoningHint: 'Financial, royalty or budget discussion detected.',
 11348	            source: 'deterministic',
 11349	        };
 11350	    }
 11351	
 11352	    if (/(spotify|apple music|playlist|isrc|upc|ddex|distribute|release date)/.test(combined)) {
 11353	        return {
 11354	            recommendedTab: 'module',
 11355	            recommendedModule: 'distribution',
 11356	            confidence: 0.85,
 11357	            reasoningHint: 'Release distribution or DSP delivery discussion detected.',
 11358	            source: 'deterministic',
 11359	        };
 11360	    }
 11361	
 11362	    if (/(browse|url|website|webpage|search|article|link)/.test(combined)) {
 11363	        return {
 11364	            recommendedTab: 'browser',
 11365	            confidence: 0.8,
 11366	            reasoningHint: 'Web research or link referenced in conversation.',
 11367	            source: 'deterministic',
 11368	        };
 11369	    }
 11370	
 11371	    if (/(kill switch|worker|telemetry|active agent|subagent|daemon|running task)/.test(combined)) {
