 11388	export async function judgeBoardroomWorkspaceRecommendation(
 11389	    messages: { role: string; text?: string }[]
 11390	): Promise<BoardroomWorkspaceRecommendation> {
 11391	    const fallback = heuristicBoardroomWorkspaceRecommendation(messages);
 11392	    if (!judgmentsAvailable("judgeBoardroomWorkspaceRecommendation") || messages.length === 0) {
 11393	        return fallback;
 11394	    }
 11395	
 11396	    try {
 11397	        const judgeFn = httpsCallable<
 11398	            { state: Record<string, unknown>; questions: Record<string, unknown> },
 11399	            { answers: Record<string, unknown> }
 11400	        >(getFunctions(), 'typesafeJudge');
 11401	
 11402	        const recentSummary = messages
 11403	            .slice(-4)
 11404	            .map(m => `${m.role.toUpperCase()}: ${(m.text || '').slice(0, 150)}`)
 11405	            .join('\n');
 11406	
 11407	        const result = await judgeFn({
 11408	            state: { conversation: recentSummary },
 11409	            questions: {
 11410	                recommended_tab: {
 11411	                    type: 'choice' as const,
 11412	                    instructions:
 11413	                        'Based on what the boardroom team is currently discussing, which workspace tool should be actively open?',
 11414	                    criteria: {
 11415	                        workbench: 'Inspecting documents, split sheets, Markdown artifacts, or generated media assets',
 11416	                        module: 'Previewing or interacting with an indii studio department module (Creative, Finance, Legal, etc.)',
 11417	                        browser: 'Researching live music industry websites, DSP portals, or documentation',
 11418	                        'agent-feed': 'Monitoring live autonomous agent browser feeds, tasks, or graph executions',
 11419	                    },
 11420	                },
 11421	                recommended_module: {
 11422	                    type: 'choice' as const,
 11423	                    instructions:
 11424	                        'If an in-place studio module preview is recommended or helpful, which department module is most relevant?',
 11425	                    criteria: {
 11426	                        creative: 'Album artwork, video editing, canvas designs, visual styling',
 11427	                        publishing: 'Songwriting splits, mechanical royalties, PRO registrations',
 11428	                        finance: 'Budgets, financial analytics, expenses, streaming revenue',
 11429	                        legal: 'Contracts, split sheets, copyright governance, rights clearances',
 11430	                        marketing: 'Advertising campaigns, press pitching, release rollout',
 11431	                        social: 'TikTok/Instagram content, community engagement',
 11432	                        distribution: 'DSP deliveries, metadata verification, release packaging',
 11433	                    },
 11434	                },
 11435	            },
 11436	        });
 11437	
 11438	        const validTabs: BoardroomWorkspaceRecommendation['recommendedTab'][] = ['browser', 'module', 'workbench', 'agent-feed'];
 11439	        const validMods: NonNullable<BoardroomWorkspaceRecommendation['recommendedModule']>[] = [
 11440	            'creative', 'publishing', 'finance', 'legal', 'marketing', 'social', 'distribution'
 11441	        ];
 11442	
 11443	        const tabAns = result.data?.answers?.recommended_tab;
 11444	        const tabChoice = whitelistedChoice(tabAns, validTabs);
 11445	        const tabConf = boundedConfidenceValue(tabAns);
 11446	
 11447	        const modAns = result.data?.answers?.recommended_module;
 11448	        const modChoice = whitelistedChoice(modAns, validMods);
 11449	        const modConf = boundedConfidenceValue(modAns);
 11450	
 11451	        if (tabChoice === null || (tabConf !== null && tabConf < 0.5)) {
 11452	            return fallback;
 11453	        }
 11454	        const useMod = modChoice !== null && (modConf === null || modConf >= 0.5);
 11455	        const resolvedConfidence = tabConf !== null && modConf !== null && useMod
 11456	            ? Math.min(tabConf, modConf)
 11457	            : (tabConf ?? modConf ?? 0.95);
 11458	
 11459	        return {
 11460	            recommendedTab: tabChoice,
 11461	            recommendedModule: useMod ? modChoice : fallback.recommendedModule,
 11462	            confidence: resolvedConfidence,
 11463	            reasoningHint: 'Recommended by TypeSafe Jev System One.',
 11464	            source: 'jev',
 11465	        };
 11466	    } catch (err: unknown) {
 11467	        noteJudgmentFailure(err, 'boardroom workspace recommendation judgment', "judgeBoardroomWorkspaceRecommendation");
 11468	        return fallback;
 11469	    }
 11470	}
